namespace probe.mutability
main {
    7 => it!
    it! -> println
}

compute input: Int -> Int {
    7 => local!
    local! + input
}
main { 0 -> compute -> println }

main {
    [1, 2] -> each item {
        item => local!
        local! -> println
    }
}

main {
    true -> if {
        7 => value!
        value! -> println
    } else {
        8 => value!
        value! + 1 => value!
        value! -> println
    }
}

reserve values: ref [Int; ~], size: Int -> Unit { }
main {
    [Int; ~] => values!
    values! -> reserve(8)
    values! -> len -> println
}
